import { AbstractControl, ValidationErrors, ValidatorFn } from '@angular/forms';

export const noSpaces: ValidatorFn = (control: AbstractControl): ValidationErrors | null =>
  typeof control.value === 'string' && control.value.includes(' ')
    ? { noSpaces: true }
    : null;

export const endAfterStart: ValidatorFn = (group: AbstractControl): ValidationErrors | null => {
  const start = group.get('start')?.value;
  const end = group.get('end')?.value;
  return start && end && end <= start ? { endBeforeStart: true } : null;
};

