import { Pipe, PipeTransform } from '@angular/core';

@Pipe({ name: 'minutes' })
export class MinutesPipe implements PipeTransform {
  transform(total: number): string {
    const h = Math.floor(total / 60);
    const m = total % 60;
    return h > 0 ? `${h} h ${m} min` : `${m} min`;
  }
}

