import { Component, effect, inject, input, output } from '@angular/core';
import { FormBuilder, ReactiveFormsModule, Validators } from '@angular/forms';

export interface Course { id: number; title: string; hours: number; }

@Component({
  selector: 'app-course-editor',
  imports: [ReactiveFormsModule],
  template: `
    <form [formGroup]="form" (ngSubmit)="submit()">
      <input formControlName="title" aria-label="Title">
      <input formControlName="hours" type="number" aria-label="Hours">
      <button type="submit">{{ course() ? 'Save changes' : 'Add course' }}</button>
    </form>
  `,
})
export class CourseEditor {
  readonly course = input<Course | null>(null);
  readonly saved = output<{ title: string; hours: number }>();

  protected readonly form = inject(FormBuilder).nonNullable.group({
    title: ['', Validators.required],
    hours: [3, Validators.min(1)],
  });

  constructor() {
    effect(() => {
      const c = this.course();
      this.form.reset(c ? { title: c.title, hours: c.hours } : { title: '', hours: 3 });
    });
  }

  protected submit(): void {
    if (this.form.invalid) { this.form.markAllAsTouched(); return; }
    this.saved.emit(this.form.getRawValue());
  }
}

protected remove(course: Course): void {
  if (!confirm(`Delete "${course.title}"? This cannot be undone.`)) return;

  this.api.remove(course.id).subscribe({
    next: () => {
      this.courses.update(list => list.filter(c => c.id !== course.id));
      this.toast.show(`"${course.title}" was deleted`);
    },
    error: () => this.toast.show('Could not delete the course. Try again.'),
  });
}

